===== OwnerAddress =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

/**
 * Single source of truth for the owner-address normalization rule, applied whenever an owner is
 * created. A raw address is reduced to a canonical stored form: surrounding and repeated whitespace
 * collapsed to single spaces, upper-cased, and common street-type abbreviations expanded to their
 * full words ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
 *
 * <p>The same normalized form is what gets stored and returned, what the required-field check tests
 * for blankness, and what every address comparison uses — household duplicate detection and the
 * shared household id both reduce through {@link #normalize} (see {@link OwnerHousehold}).
 */
final class OwnerAddress {

    private OwnerAddress() {
    }

    /**
     * Reduces an address to its canonical form: trimmed, inner runs of whitespace collapsed to a
     * single space, upper-cased, with common abbreviations expanded token by token. A {@code null}
     * value yields an empty string.
     */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        for (int i = 0; i < tokens.length; i++) {
            switch (tokens[i]) {
                case "ST":
                    tokens[i] = "STREET";
                    break;
                case "RD":
                    tokens[i] = "ROAD";
                    break;
                case "AVE":
                    tokens[i] = "AVENUE";
                    break;
                default:
                    break;
            }
        }
        return String.join(" ", tokens);
    }
}
===== OwnerHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * Single source of truth for the owner-household identity rule. A household is keyed on
 * {@code (lastName, postcode)}: two owners whose normalized last names match and whose postcodes are
 * equal belong to the same household and therefore share the same {@link #householdId}. The id is
 * <em>deterministic</em> — it is computed purely from those two values, so every owner that joins a
 * household arrives at the same id independently, without coordinating through the database.
 *
 * <p>Used by {@link AssignOwnerHousehold} to stamp the id onto a new owner, by
 * {@link CheckOwnerHouseholdUnique} to detect a second owner in the same household, and by
 * {@link OwnerIdentity} to derive the household segment of an owner's identity key — so the
 * definition of "same household" lives here and nowhere else.
 */
final class OwnerHousehold {

    private OwnerHousehold() {
    }

    /**
     * Reduces a value to its comparison form: trimmed, inner runs of whitespace collapsed to a
     * single space, and lower-cased. A {@code null} value yields an empty string.
     */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /**
     * Derives the stable household identifier shared by every owner in the same household. Owners
     * whose normalized last name and postcode match produce the same value, so the id can be computed
     * independently for each joining owner without coordinating through the database. The value is
     * the first 12 upper-case hex characters of the SHA-256 of the normalized
     * {@code "<lastName>|<postcode>"}.
     *
     * <p>A household requires a postcode: when the postcode is {@code null} or blank the owner
     * belongs to no household and this returns {@code null}.
     */
    static String householdId(String lastName, String postcode) {
        if (postcode == null || postcode.isBlank()) {
            return null;
        }
        String key = normalize(lastName) + "|" + postcode.trim();
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }
}
===== ValidateOwner =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.List;

import jakarta.validation.Valid;
import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.model.OwnerRegion;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Validates before {@link LoadOwner} runs, so an invalid body is a 400 even when the owner does not exist.
 */
@Validated
public class ValidateOwner {

    public void service(@Valid @RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws OwnerFieldsInvalidException {
        // Postcode is optional; when present it must be valid for the city's region (an unknown
        // region accepts any 4-digit postcode), mirroring the create pipeline.
        String postcode = request.getPostcode();
        if (postcode != null && !OwnerRegion.isPostcodeValid(request.getCity(), postcode)) {
            throw new OwnerFieldsInvalidException(List.of("postcode"));
        }
        validated.set(request);
    }
}
===== ValidateOwnerFields =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.model.OwnerRegion;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Rejects a create request that is missing or blank in any required owner field.
 *
 * <p>Runs first in the {@code POST /api/owners} pipeline. It binds the body once (this is the only
 * step that reads {@code @RequestBody}) and republishes it for {@link BuildOwner}. Each of
 * firstName, lastName, address, city and telephone must be present and non-blank; any that are not
 * are collected and reported together via {@link OwnerFieldsInvalidException}. A supplied
 * registrationDate must not be later than the server's current date.
 *
 * <p>The telephone is converted to E.164 form (see {@link OwnerTelephone#toE164}). The E.164 value
 * replaces the submitted one on the republished body, so it is what gets stored and returned. A
 * number that cannot form valid E.164 is rejected as an invalid {@code telephone}.
 */
public class ValidateOwnerFields {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws OwnerFieldsInvalidException {
        List<String> errors = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            errors.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            errors.add("lastName");
        }
        // The address is normalized (whitespace collapsed, upper-cased, abbreviations expanded)
        // before the required-field check, so an address that is blank only after normalization is
        // rejected; the normalized value replaces the submitted one, so it is what gets stored,
        // returned and compared for household identity.
        String address = OwnerAddress.normalize(request.getAddress());
        if (address.isEmpty()) {
            errors.add("address");
        }
        else {
            request.setAddress(address);
        }
        if (isBlank(request.getCity())) {
            errors.add("city");
        }
        if (isBlank(request.getTelephone())) {
            errors.add("telephone");
        }
        else {
            String telephone = OwnerTelephone.toE164(request.getTelephone());
            if (telephone == null) {
                errors.add("telephone");
            }
            else {
                request.setTelephone(telephone);
            }
        }
        // Email is optional. When present it must be syntactically valid and its domain must not be a
        // known disposable provider; it is normalized to lower case so it is stored and returned
        // lower-cased.
        String email = request.getEmail();
        if (email != null) {
            if (!OwnerEmail.isValid(email) || OwnerEmail.isDisposable(email)) {
                errors.add("email");
            }
            else {
                request.setEmail(OwnerEmail.normalize(email));
            }
        }
        // Postcode is optional. When present it must be exactly four digits and, for a city with a
        // known region, fall within that region's postcode range; a city with no known region
        // accepts any 4-digit postcode. An absent postcode leaves the owner backward-compatible.
        String postcode = request.getPostcode();
        if (postcode != null && !OwnerRegion.isPostcodeValid(request.getCity(), postcode)) {
            errors.add("postcode");
        }
        // Registration date is optional and defaults to the server date when omitted. When supplied
        // it may not be in the future: a date later than the server's current date is rejected.
        LocalDate registrationDate = request.getRegistrationDate();
        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
            errors.add("registrationDate");
        }
        if (!errors.isEmpty()) {
            throw new OwnerFieldsInvalidException(errors);
        }
        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
===== BuildOwner =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        // Store the effective registration date (supplied or defaulted, rolled to a business day).
        // Values derived from it (e.g. the membership number's year segment) are assigned by later
        // steps and so pick up this adjusted date.
        owner.setRegistrationDate(BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate()));
        built.set(owner);
    }
}
