47	        if (isBlank(request.getCity())) {
48	            errors.add("city");
49	        }
50	        if (isBlank(request.getTelephone())) {
51	            errors.add("telephone");
52	        }
53	        else {
54	            String telephone = OwnerTelephone.toE164(request.getTelephone());
55	            if (telephone == null) {
56	                errors.add("telephone");
57	            }
58	            else {
59	                request.setTelephone(telephone);
60	            }
61	        }
62	        // Email is optional. When present it must be syntactically valid and its domain must not be a
63	        // known disposable provider; it is normalized to lower case so it is stored and returned
64	        // lower-cased.
65	        String email = request.getEmail();
66	        if (email != null) {
67	            if (!OwnerEmail.isValid(email) || OwnerEmail.isDisposable(email)) {
68	                errors.add("email");
69	            }
70	            else {
71	                request.setEmail(OwnerEmail.normalize(email));
72	            }
73	        }
74	        // Postcode is optional. When present it must be exactly four digits and, for a city with a
75	        // known region, fall within that region's postcode range; a city with no known region
76	        // accepts any 4-digit postcode. An absent postcode leaves the owner backward-compatible.
77	        String postcode = request.getPostcode();
78	        if (postcode != null && !OwnerRegion.isPostcodeValid(request.getCity(), postcode)) {
79	            errors.add("postcode");
80	        }
81	        // Registration date is optional and defaults to the server date when omitted. When supplied
82	        // it may not be in the future: a date later than the server's current date is rejected.
83	        LocalDate registrationDate = request.getRegistrationDate();
84	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
85	            errors.add("registrationDate");
86	        }
87	        if (!errors.isEmpty()) {
88	            throw new OwnerFieldsInvalidException(errors);
89	        }
90	        validated.set(request);
91	    }
92	
93	    private static boolean isBlank(String value) {
94	        return value == null || value.isBlank();
95	    }
96	}
