1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.Map;
4	
5	/**
6	 * Single source of truth for the fixed city-to-region table and the per-region postcode ranges.
7	 *
8	 * <p>This is a domain concept shared by the read-time {@code locality} derivation (see
9	 * {@code org.springframework.samples.petclinic.mapper.OwnerMapper}) and the create/update postcode
10	 * validation in the REST pipeline, so it lives in the business layer that both already depend on
11	 * rather than in either. A city not in the table has region {@link #UNKNOWN} and accepts any 4-digit
12	 * postcode.
13	 */
14	public final class OwnerRegion {
15	
16	    /** Region reported for a city that is not in the fixed table. */
17	    public static final String UNKNOWN = "UNKNOWN";
18	
19	    /** Fixed city-to-region table; any other city has region {@link #UNKNOWN}. */
20	    private static final Map<String, String> CITY_REGION = Map.of(
21	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
22	
23	    /** Region to inclusive 4-digit postcode range {@code {low, high}}. */
24	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
25	        "NSW", new int[] {2000, 2099},
26	        "VIC", new int[] {3000, 3099},
27	        "QLD", new int[] {4000, 4099});
28	
29	    /** Fixed region-to-timezone table, as IANA names; any other region has no timezone. */
30	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
31	        "NSW", "Australia/Sydney",
32	        "VIC", "Australia/Melbourne",
33	        "QLD", "Australia/Brisbane");
34	
35	    private OwnerRegion() {
36	    }
37	
38	    /** The canonical region for {@code city}, or {@link #UNKNOWN} when the city is not in the table. */
39	    public static String regionOf(String city) {
40	        return CITY_REGION.getOrDefault(city, UNKNOWN);
41	    }
42	
43	    /**
44	     * The IANA timezone name for {@code region} from the fixed region-to-timezone table
45	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane), or
46	     * {@code null} when the region (e.g. {@link #UNKNOWN}) has no mapping.
47	     */
48	    public static String timezoneOf(String region) {
49	        return REGION_TIMEZONE.get(region);
50	    }
51	
52	    /**
53	     * The locality for an owner, preferring the postcode: when {@code postcode} is a 4-digit value
54	     * inside a known region's range that region wins, disambiguating cities that share a name.
55	     * Otherwise (postcode absent, malformed, or in no known range) this falls back to the
56	     * city-to-region table, which still returns {@link #UNKNOWN} for an unknown city.
57	     */
58	    public static String localityOf(String city, String postcode) {
59	        String byPostcode = regionForPostcode(postcode);
60	        return byPostcode != null ? byPostcode : regionOf(city);
61	    }
62	
63	    /** The region whose inclusive range contains {@code postcode}, or {@code null} when none does. */
64	    private static String regionForPostcode(String postcode) {
65	        if (postcode == null || !postcode.matches("\\d{4}")) {
66	            return null;
67	        }
68	        int value = Integer.parseInt(postcode);
69	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
70	            int[] range = entry.getValue();
71	            if (value >= range[0] && value <= range[1]) {
72	                return entry.getKey();
73	            }
74	        }
75	        return null;
76	    }
77	
78	    /**
79	     * Whether {@code postcode} is acceptable for {@code city}. A postcode must be exactly four
80	     * digits; a city whose region is known must additionally fall within that region's inclusive
81	     * range, while a city with no known region accepts any 4-digit postcode.
82	     */
83	    public static boolean isPostcodeValid(String city, String postcode) {
84	        if (postcode == null || !postcode.matches("\\d{4}")) {
85	            return false;
86	        }
87	        int[] range = REGION_POSTCODES.get(regionOf(city));
88	        if (range == null) {
89	            return true;
90	        }
91	        int value = Integer.parseInt(postcode);
92	        return value >= range[0] && value <= range[1];
93	    }
94	}
