20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        String householdId = owner.getHouseholdId();
22	        int count = 1; // the owner being created, not yet persisted
23	        if (householdId != null) {
24	            for (Owner existing : ownerRepository.findAll()) {
25	                if (householdId.equals(existing.getHouseholdId())) {
26	                    count++;
27	                }
28	            }
29	        }
30	        owner.setHouseholdSize(count);
31	    }
32	}
