8	/**
9	 * Rejects a create request that would be a second owner in an existing household.
10	 *
11	 * <p>Runs after {@link ValidateOwnerFields} and before {@link BuildOwner}. A household is keyed on
12	 * {@code (lastName, postcode)} through the deterministic {@link OwnerHousehold#householdId}, so an
13	 * owner whose computed household id already belongs to another owner is a household duplicate and is
14	 * rejected with {@link OwnerHouseholdDuplicateException} (409 Conflict).
15	 *
16	 * <p>The {@code sharesHousehold} flag bypasses this block: when the request opts in, the owner is
17	 * created as a declared member of the household instead of being rejected. An owner with no postcode
18	 * belongs to no household (its household id is {@code null}) and so is never a household duplicate.
19	 */
20	public class CheckOwnerHouseholdUnique {
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws OwnerHouseholdDuplicateException {
24	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
25	            return; // declared household member: bypass the duplicate block
26	        }
27	        String householdId = OwnerHousehold.householdId(request.getLastName(), request.getPostcode());
28	        if (householdId == null) {
29	            return; // no postcode means no household, so no household duplicate is possible
30	        }
31	        for (Owner existing : ownerRepository.findAll()) {
32	            if (householdId.equals(existing.getHouseholdId())) {
33	                throw new OwnerHouseholdDuplicateException(householdId);
34	            }
35	        }
36	    }
37	}
