5	/**
6	 * Single source of truth for an owner's derived {@code identityKey} — the descriptive key returned
7	 * on an owner. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId},
8	 * where the telephone is reduced to E.164 through {@link OwnerTelephone#toE164} and the email
9	 * lower-cased through {@link OwnerEmail#normalize}; a missing email or household id contributes an
10	 * empty segment.
11	 *
12	 * <p>The {@code householdId} segment is the deterministic household id (see
13	 * {@link OwnerHousehold#householdId}), so two owners in the same household share that segment.
14	 * Duplicate detection itself keys off the household id directly (see {@link CheckOwnerHouseholdUnique});
15	 * this class only derives the key the owner mapper returns.
16	 */
17	public final class OwnerIdentity {
18	
19	    private OwnerIdentity() {
20	    }
21	
22	    /**
23	     * Builds the identity key from its three raw parts: the submitted/stored telephone (normalized
24	     * to E.164 here), the email (lower-cased here) and the already-derived household id. Any part
25	     * that is {@code null} or cannot normalize contributes an empty segment.
26	     */
27	    public static String identityKey(String telephone, String email, String householdId) {
28	        String normalizedTelephone = OwnerTelephone.toE164(telephone);
29	        String normalizedEmail = OwnerEmail.normalize(email);
30	        return (normalizedTelephone == null ? "" : normalizedTelephone) + "|"
31	                + (normalizedEmail == null ? "" : normalizedEmail) + "|"
32	                + (householdId == null ? "" : householdId);
33	    }
34	
35	    /**
36	     * The identity key of an already-stored owner, read from its persisted fields. The single
37	     * {@code Owner}-to-key definition used by the owner mapper to return the descriptive key.
38	     */
39	    public static String identityKey(Owner owner) {
40	        return identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
41	    }
42	}
